import {MONTHS,FIELDS,HEADERS,analyse,recommendations,demoRows,parseSheets} from './model.js';
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>n===null||n===undefined?'—':new Intl.NumberFormat('en-GB',{maximumFractionDigits:1}).format(n);const compact=n=>new Intl.NumberFormat('en-GB',{notation:'compact',maximumFractionDigits:1}).format(n);const pct=n=>n===null?'—':`${n.toFixed(1)}%`;
let rows=demoRows(),isDemo=true,sourceNames=[],results=[],selected='Oxytocin 10 IU / mL';
const state={programme:'all',start:1,end:8,low:3,high:6};
['start-month','end-month'].forEach(id=>{$(id).innerHTML=MONTHS.map((m,i)=>`<option value="${i+1}">${m.slice(0,3)} 2026</option>`).join('');});$('end-month').value='8';
function getActions(){return results.flatMap(c=>recommendations(c,state.low,state.high)).sort((a,b)=>({danger:0,warning:1,neutral:2}[a.tone]-{danger:0,warning:1,neutral:2}[b.tone]));}
function render(){
 results=analyse(rows,state);const scores=results.map(c=>c.accuracy).filter(n=>n!==null);const mean=scores.length?scores.reduce((s,v)=>s+v,0)/scores.length:null;const low=results.filter(c=>c.stock===0||(c.mos!==null&&c.mos<state.low)).length;const complete=results.filter(c=>c.complete).length;const pairs=results.reduce((s,c)=>s+c.pairs,0);const expected=results.length*(state.end-state.start+1);
 $('coverage-label').textContent=`${pairs} / ${expected} matched months`;
 const cards=[['Commodities reviewed',results.length,'Across the selected programmes','▦'],['Mean forecast accuracy',pct(mean),`${scores.length} commodity scores · equal weight`,'◎'],['Low / zero stock',low,`At ${MONTHS[state.end-1]} close · < ${state.low} months`,'⚑'],['Demand data complete',`${complete}<small>/ ${results.length}</small>`,'All selected forecast–consumption pairs','✓']];
 $('kpis').innerHTML=cards.map(([label,value,note,icon])=>`<article class="kpi"><span class="kpi-icon">${icon}</span><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></article>`).join('');
 const gaps=results.filter(c=>c.needsData||c.accuracy===null).length;const mismatch=results.filter(c=>c.accuracy!==null&&c.accuracy<80).length;
 $('overview-insight').innerHTML=results.length?`<b>Review focus:</b> ${low} ${low===1?'commodity needs':'commodities need'} a replenishment review, ${mismatch} have accuracy below 80%, and ${gaps} need additional data checks. ${isDemo?'<b>Illustrative findings only.</b>':''}`:'No commodities match this selection. Change the programme or import a dataset.';
 if(!results.some(c=>c.name===selected))selected=results[0]?.name??'';
 $('commodity').innerHTML=results.length?results.map(c=>`<option ${c.name===selected?'selected':''} value="${esc(c.name)}">${esc(c.name)}</option>`).join(''):'<option>No commodities</option>';
 $('commodity').disabled=!results.length;
 renderCharts();renderTable();renderRisks();
 $('source-banner').innerHTML=isDemo?'<span><b>DEMONSTRATION DATA</b> Explore illustrative quantities. Import your files for the actual review.</span><button id="template-top">Download template ↗</button>':`<span><b>IMPORTED DATA</b> ${rows.length} rows from ${sourceNames.length} file${sourceNames.length===1?'':'s'} · browser session only · ${esc(sourceNames.join(', '))}</span><button id="template-top">Download template ↗</button>`;
 $('template-top').onclick=downloadTemplate;
}
function chart(c,fields,colors,type){
 if(!c)return '<div class="empty">No commodity selected.</div>';
 const months=Array.from({length:state.end-state.start+1},(_,i)=>i+state.start);const data=months.map(m=>c.rows.find(r=>r.month===m));const values=data.flatMap(r=>fields.map(f=>r?.[f]??null)).filter(v=>v!==null);if(!values.length)return '<div class="empty">No reported quantities for this chart.</div>';
 const width=620,height=270,left=54,right=22,top=26,bottom=43;const plotW=width-left-right,plotH=height-top-bottom,max=Math.max(1,...values)*1.18;const x=i=>left+plotW*(i+.5)/months.length;const y=v=>height-bottom-v/max*plotH;
 let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(c.name)}: monthly ${fields.join(' and ')} chart. Exact values are in commodity detail."><title>${esc(c.name)} · ${fields.join(' vs ')}</title>`;
 for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${left}" y1="${y(v)}" x2="${width-right}" y2="${y(v)}" stroke="#edf0f6" ${i?'stroke-dasharray="4 4"':''}/><text x="${left-10}" y="${y(v)+4}" text-anchor="end" fill="#7e9387" font-size="11">${compact(v)}</text>`;}
 months.forEach((m,i)=>svg+=`<text x="${x(i)}" y="${height-17}" text-anchor="middle" fill="#6c8375" font-size="12">${MONTHS[m-1].slice(0,3)}</text>`);
 fields.forEach((field,series)=>{
  if(type==='line'){
   let segment=[];const segments=[];data.forEach((r,i)=>{const v=r?.[field];if(v===null||v===undefined){if(segment.length)segments.push(segment);segment=[];}else segment.push([x(i),y(v)]);});if(segment.length)segments.push(segment);
   segments.forEach(points=>svg+=`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${colors[series]}" stroke-width="3" stroke-linejoin="round" ${series===0?'stroke-dasharray="6 5"':''}/>`);
  }
  data.forEach((r,i)=>{const v=r?.[field];if(v===null||v===undefined)return;const title=`${MONTHS[months[i]-1]} ${field}: ${fmt(v)}`;if(type==='line')svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="${colors[series]}" stroke-width="2"><title>${title}</title></circle>`;else{const w=Math.min(18,plotW/months.length*.24);svg+=`<rect x="${x(i)+(series===0?-w-2:2)}" y="${y(v)}" width="${w}" height="${Math.max(0,height-bottom-y(v))}" fill="${colors[series]}" rx="3"><title>${title}</title></rect>`;}});
 });return svg+'</svg>';
}
function renderCharts(){const c=results.find(c=>c.name===selected);$('demand-chart').innerHTML=chart(c,['Forecast','Consumption'],['#127447','#69a84d'],'line');$('supply-chart').innerHTML=chart(c,['Receipts','Issues'],['#69a84d','#b6d68b'],'bar');$('selected-summary').innerHTML=c?`<span>${esc(c.name)}</span><span>${c.pairs}/${c.expected} matched months</span><span>Accuracy ${pct(c.accuracy)}</span><span>End-month stock cover ${c.mos===null?'unavailable':`${c.mos.toFixed(1)} months`}</span><span>Gaps represent unreported values</span>`:'';}
function renderTable(){const query=$('search').value.trim().toLowerCase();const filtered=results.filter(c=>c.name.toLowerCase().includes(query));$('performance-body').innerHTML=filtered.map(c=>`<tr><td><button class="commodity-link" data-name="${esc(c.name)}">${esc(c.name)}</button><small>${esc(c.programme)}</small></td>${['Forecast','Consumption','Issues','Receipts'].map(f=>`<td>${fmt(c.totals[f])}${c.counts[f]!==c.expected?`<small>${c.counts[f]}/${c.expected} months</small>`:''}</td>`).join('')}<td class="${c.variance>0?'positive':'negative'}">${c.variance>0?'+':''}${fmt(c.variance)}<small>${c.variancePct===null?'No % baseline':`${c.variancePct>0?'+':''}${pct(c.variancePct)}`} · ${c.pairs} pairs</small></td><td><div class="accuracy-cell">${c.accuracy===null?'':`<span class="accuracy-bar"><i style="width:${c.accuracy}%"></i></span>`}${pct(c.accuracy)}</div></td><td>${c.mos===null?'—':c.mos.toFixed(1)+' mo'}<small>${MONTHS[state.end-1].slice(0,3)} close</small></td><td><span class="badge ${c.tone}">${c.status}</span></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No matching commodities. Clear the search or change your filters.</td></tr>';$('table-count').textContent=`${filtered.length} of ${results.length} commodities`;document.querySelectorAll('.commodity-link').forEach(button=>button.onclick=()=>openDetail(button.dataset.name));}
function renderRisks(){const actions=getActions();$('risk-list').innerHTML=actions.map(a=>`<article class="risk-card ${a.tone}"><span class="badge ${a.tone}">${esc(a.title)}</span><h3>${esc(a.commodity)}</h3><p>${esc(a.reason)}</p><p class="action"><b>Next action →</b> ${esc(a.action)}</p></article>`).join('')||'<div class="panel empty">No review flags in this selection. Continue routine pipeline and expiry checks.</div>';}
function openDetail(name){const c=results.find(c=>c.name===name);if(!c)return;selected=name;$('commodity').value=name;renderCharts();$('detail-title').textContent=name;const months=Array.from({length:c.expected},(_,i)=>i+state.start);$('detail-content').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Month</th>${FIELDS.map(f=>`<th>${f}</th>`).join('')}<th>Variance</th><th>Accuracy</th></tr></thead><tbody>${months.map(month=>{const r=c.rows.find(r=>r.month===month);const matched=r&&r.Forecast!==null&&r.Consumption!==null;return `<tr><td>${MONTHS[month-1]} 2026</td>${FIELDS.map(f=>`<td>${fmt(r?.[f])}</td>`).join('')}<td>${matched?fmt(r.Consumption-r.Forecast):'—'}</td><td>${matched&&r.Consumption>0?pct(Math.max(0,1-Math.abs(r.Consumption-r.Forecast)/r.Consumption)*100):'—'}</td></tr>`;}).join('')}</tbody></table></div><p class="detail-note">Period accuracy: <b>${pct(c.accuracy)}</b> from ${c.pairs} matched months. Closing stock: <b>${fmt(c.stock)}</b> in ${MONTHS[c.end-1]}. Trailing average monthly consumption: <b>${fmt(c.amc)}</b>. Months of stock: <b>${c.mos===null?'unavailable':c.mos.toFixed(1)}</b>.<br>Use the same reporting unit and pack size for every measure of this commodity. Verify potential stockout-suppressed consumption before revising demand.</p>`;$('detail').showModal();}
function downloadBlob(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeCSV(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s)&&typeof value!=='number')s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function csv(data){return '\ufeff'+data.map(row=>row.map(safeCSV).join(',')).join('\r\n');}
function downloadTemplate(){const grid=[HEADERS,...MONTHS.map((m,i)=>['Oxytocin 10 IU / mL','Maternal health',`2026-${String(i+1).padStart(2,'0')}`,'','','','',''])];if(!window.XLSX){downloadBlob(csv(grid),'Forecast_Review_Template_2026.csv','text/csv');return;}const wb=XLSX.utils.book_new();const sheet=XLSX.utils.aoa_to_sheet(grid);sheet['!cols']=HEADERS.map((h,i)=>({wch:i===0?32:i===1?22:17}));XLSX.utils.book_append_sheet(wb,sheet,'Monthly data');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['FORECAST REVIEW — JANUARY–AUGUST 2026'],['Enter quantities in Monthly data; duplicate the eight rows for each additional commodity.'],['Use one row per commodity-month. Remove unused blank template rows.'],['Keep strengths, units and pack sizes in the commodity name. All measures for a product must use that same unit.'],['Month: YYYY-MM, month name (assumed 2026), or an Excel date cell.'],['Programme: Family planning / Maternal health / Unclassified; blank triggers name-based classification.'],['Blank means missing; 0 means reported zero. Do not enter dashes or N/A.'],['Select all review files together. Imports replace the current browser-session dataset.'],['The dashboard reports validation errors and rejects duplicates rather than summing them.']]),'Instructions');XLSX.writeFile(wb,'Forecast_Review_Template_2026.xlsx');}
function exportReview(){const data=[['Forecast Review',isDemo?'DEMONSTRATION DATA — illustrative only':'IMPORTED DATA'],['Period',`${MONTHS[state.start-1]}–${MONTHS[state.end-1]} 2026`],['Programme',state.programme],['Stock thresholds',`Low < ${state.low}; high > ${state.high} months`],['Accuracy method','max(0, 1 - sum absolute monthly errors / sum consumption) x 100; paired months only'],['Variance method','Consumption minus forecast; paired months only'],['Stock cover method','Selected end-month closing stock / complete trailing up-to-3-month average consumption'],[],['Commodity','Programme','Forecast','Consumption','Issues','Receipts','Variance','Variance %','Accuracy %','Months of stock','Closing Stock (end month)','Matched months','Expected months','Status'],...results.map(c=>[c.name,c.programme,...['Forecast','Consumption','Issues','Receipts'].map(f=>c.totals[f]),c.variance,c.variancePct,c.accuracy,c.mos,c.stock,c.pairs,c.expected,c.status]),[],['Commodity','Priority','Evidence','Recommended action'],...getActions().map(a=>[a.commodity,a.title,a.reason,a.action]),[],['Monthly source data',isDemo?'DEMONSTRATION':'IMPORTED'],HEADERS,...rows.filter(r=>(state.programme==='all'||r.programme===state.programme)&&r.month>=state.start&&r.month<=state.end).map(r=>[r.commodity,r.programme,`2026-${String(r.month).padStart(2,'0')}`,...FIELDS.map(f=>r[f])])];downloadBlob(csv(data),`Forecast_Review_${isDemo?'DEMO_':''}2026_${state.start}-${state.end}.csv`,'text/csv;charset=utf-8');}
async function importFiles(files){if(!files.length)return;if(!window.XLSX){$('import-status').className='error';$('import-status').textContent='The Excel reader could not load. Reload the page and try again.';return;}const status=$('import-status');status.className='';status.textContent='Reading and validating your files…';$('file-input').disabled=true;try{const sheets=[];let totalSize=0;for(const file of files){totalSize+=file.size;if(totalSize>40*1024*1024)throw new Error('Please keep the combined file size below 40 MB.');if(!/\.(xlsx|xls|csv)$/i.test(file.name))throw new Error(`Unsupported file type: ${file.name}`);const buffer=await file.arrayBuffer();const workbook=XLSX.read(buffer,{type:'array',cellDates:true,raw:true});for(const name of workbook.SheetNames){const sheet=workbook.Sheets[name];if(sheet['!ref']){const range=XLSX.utils.decode_range(sheet['!ref']);if(range.e.r>50000||range.e.c>500)throw new Error(`${file.name} / ${name}: sheet too large. Use a clean extract with up to 50,000 rows and 500 columns.`);}sheets.push({name:`${file.name} / ${name}`,data:XLSX.utils.sheet_to_json(sheet,{header:1,defval:null,raw:true,blankrows:true})});}}const parsed=parseSheets(sheets);if(parsed.errors.length){status.className='error';status.textContent=`Import not applied: ${parsed.errors.length} issue(s). Your current data is unchanged.\n${parsed.errors.slice(0,30).join('\n')}${parsed.errors.length>30?'\nAdditional issues omitted. Fix these and retry.':''}`;return;}rows=parsed.rows;isDemo=false;sourceNames=Array.from(files,f=>f.name);state.programme='all';state.start=1;state.end=8;syncControls();$('search').value='';render();status.textContent=`Imported ${rows.length} rows from ${files.length} file(s).\n${parsed.warnings.join('\n')}\n${rows.filter(r=>r.programme==='Unclassified').length} row(s) need programme classification. Review data coverage before using the results.`;}catch(error){status.className='error';status.textContent=`Import not applied. ${error.message}`;}finally{$('file-input').value='';$('file-input').disabled=false;}}
function syncControls(){$('programme').value=state.programme;$('start-month').value=state.start;$('end-month').value=state.end;}
$('programme').onchange=e=>{state.programme=e.target.value;render();};$('start-month').onchange=e=>{state.start=+e.target.value;if(state.start>state.end)state.end=state.start;syncControls();render();};$('end-month').onchange=e=>{state.end=+e.target.value;if(state.end<state.start)state.start=state.end;syncControls();render();};$('commodity').onchange=e=>{selected=e.target.value;renderCharts();};$('search').oninput=renderTable;
$('reset').onclick=()=>{Object.assign(state,{programme:'all',start:1,end:8});syncControls();$('search').value='';render();};
['low-stock','high-stock'].forEach(id=>{$(id).onchange=()=>{const low=+$('low-stock').value,high=+$('high-stock').value;if(!Number.isFinite(low)||!Number.isFinite(high)||low<0||high<=low||high>120||low>100){$(id).setCustomValidity('Use a low threshold of at least 0 and a higher threshold up to 120.');$(id).reportValidity();return;}['low-stock','high-stock'].forEach(id=>$(id).setCustomValidity(''));state.low=low;state.high=high;render();};});
$('upload-top').onclick=()=>{$('data').scrollIntoView({behavior:'smooth'});$('file-input').click();};$('file-input').onchange=e=>importFiles(e.target.files);$('template').onclick=downloadTemplate;$('export').onclick=exportReview;$('close-detail').onclick=()=>$('detail').close();$('demo').onclick=()=>{rows=demoRows();isDemo=true;sourceNames=[];$('import-status').textContent='Demo data restored.';$('search').value='';Object.assign(state,{programme:'all',start:1,end:8});syncControls();render();};
const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${entry.target.id}`));}},{rootMargin:'-10% 0px -60% 0px'});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));
render();
import('./webmcp.js').then(({registerReviewTools})=>registerReviewTools({getReview:()=>({mode:isDemo?'demo':'imported',filters:{...state},commodities:results.map(({rows,...c})=>c),actions:getActions()}),setFilters:filters=>{if(filters.programme!==undefined&&!['all','Family planning','Maternal health','Unclassified'].includes(filters.programme))throw new Error('Invalid programme.');const merged={...state,...filters};if(!Number.isInteger(merged.start)||!Number.isInteger(merged.end)||merged.start<1||merged.end>8||merged.start>merged.end)throw new Error('Months must be ordered integers from 1 to 8.');Object.assign(state,filters);syncControls();render();return {filters:{...state},commodityCount:results.length};}})).catch(()=>{});
